/**
 * rules.ts — TypeScript mirror of the SlipDesk Python engine
 * (src/slipdesk/scoring.py).
 *
 * Score: late_rate x 100 x 0.45 (max 45) + severity min(15, median late
 * slip) (max 15) + breach x 100 x 0.20 (max 20) + trend (Sep late rate
 * minus Jul-Aug late rate, in points, 0..10, needs >= 2 orders each side)
 * (max 10) + worst min(10, max(0, worst slip - 7) / 2) (max 10).
 * Route: score >= 45 -> ESCALATE; >= 30 -> AT_RISK; >= 12 -> WATCH;
 * otherwise RELIABLE; under 5 orders -> UNSCORED.
 * data/test-vectors.json (generated by the Python pipeline) keeps both
 * implementations in exact agreement.
 */
import type { Route, SellerRow, ScoreParts } from "./types";

export const WINDOW_START = "2017-07-01";
export const WINDOW_END = "2017-10-01";
export const SNAPSHOT_DATE = "2017-10-31";
export const MIN_ORDERS = 5;
export const TREND_MIN_ORDERS = 2;
export const ESCALATE_SCORE = 45;
export const AT_RISK_SCORE = 30;
export const WATCH_SCORE = 12;
export const LEAD_RESET_GAP = 5;

/** Python round(x, 1) with round-half-even, computed on the exact binary
 * value of the double (so 0.05 -> 0.1, like Python, while 2.25 -> 2.2). */
export function round1(x: number): number {
  if (!Number.isFinite(x)) return x;
  const buf = new ArrayBuffer(8);
  const view = new DataView(buf);
  view.setFloat64(0, Math.abs(x));
  const bits = view.getBigUint64(0);
  const expBits = Number((bits >> 52n) & 0x7ffn);
  let mantissa = bits & ((1n << 52n) - 1n);
  let exp: number;
  if (expBits === 0) {
    exp = -1074;
  } else {
    mantissa |= 1n << 52n;
    exp = expBits - 1075;
  }
  // value = mantissa * 2^exp; scale by 10 and round half-even to an integer.
  const scaledNum = mantissa * 10n;
  let q: bigint;
  if (exp >= 0) {
    q = scaledNum << BigInt(exp);
  } else {
    const denom = 1n << BigInt(-exp);
    const div = scaledNum / denom;
    const rem = scaledNum % denom;
    const twice = rem * 2n;
    if (twice > denom || (twice === denom && div % 2n === 1n)) {
      q = div + 1n;
    } else {
      q = div;
    }
  }
  const out = Number(q) / 10;
  return x < 0 ? -out : out;
}

export interface SellerStats {
  n: number;
  late_orders: number;
  late_rate: number;
  late_median_slip: number;
  max_slip: number;
  breach_rate: number;
  sep_late_rate: number;
  sep_n: number;
  ja_late_rate: number;
  ja_n: number;
}

/** Mirror of Python scoring.score_seller. */
export function scoreSeller(stats: SellerStats): { score: number; parts: ScoreParts } {
  const pLate = round1(stats.late_rate * 100 * 0.45);
  const pSeverity = round1(Math.min(15, Math.max(0, stats.late_median_slip)));
  const pBreach = round1(stats.breach_rate * 100 * 0.2);
  let pTrend = 0;
  if (stats.sep_n >= TREND_MIN_ORDERS && stats.ja_n >= TREND_MIN_ORDERS) {
    pTrend = round1(Math.max(0, Math.min(10, (stats.sep_late_rate - stats.ja_late_rate) * 100)));
  }
  const pWorst = round1(Math.min(10, Math.max(0, stats.max_slip - 7) / 2));
  const parts: ScoreParts = {
    late_rate: pLate,
    severity: pSeverity,
    breach: pBreach,
    trend: pTrend,
    worst: pWorst,
  };
  const score = round1(parts.late_rate + parts.severity + parts.breach + parts.trend + parts.worst);
  return { score, parts };
}

/** Mirror of Python scoring.route_seller. */
export function routeSeller(score: number, n: number): Route {
  if (n < MIN_ORDERS) return "UNSCORED";
  if (score >= ESCALATE_SCORE) return "ESCALATE";
  if (score >= AT_RISK_SCORE) return "AT_RISK";
  if (score >= WATCH_SCORE) return "WATCH";
  return "RELIABLE";
}

/** Mirror of Python scoring.recommended_promise_days. */
export function recommendedPromiseDays(p90TransitDays: number, promisedMedianDays: number): { rec: number; reset: boolean } {
  const rec = Math.ceil(p90TransitDays);
  return { rec, reset: rec - promisedMedianDays >= LEAD_RESET_GAP };
}

/** Mirror of Python scoring.recommended_action. */
export function recommendedAction(s: SellerRow): { action: string; instruction: string } {
  const route = s.route;
  if (route === "UNSCORED" || route === "RELIABLE") {
    return { action: "NO ACTION", instruction: "Promise is holding. No chase, no lead-time change." };
  }
  if (s.reset_lead_time && (route === "ESCALATE" || route === "AT_RISK")) {
    return {
      action: "RESET LEAD TIME",
      instruction: `Reset the promised lead time from ${s.promised_median_days} to ${s.recommended_promise_days} days: p90 actual transit is ${s.p90_transit_days} days, so the current promise is unkeepable.`,
    };
  }
  if (s.overdue_open >= 3) {
    return {
      action: "CHASE OVERDUE ORDERS",
      instruction: `${s.overdue_open} orders are past their promised date and still not delivered as of ${SNAPSHOT_DATE}. Chase the seller today.`,
    };
  }
  if (s.breach_rate >= 0.25) {
    return {
      action: "FIX SHIP-BY DISCIPLINE",
      instruction: `${Math.round(s.breach_rate * 100)}% of items shipped after the shipping-limit date. The slip starts in the warehouse, not with the carrier.`,
    };
  }
  if (s.late_rate >= 0.2) {
    return {
      action: "CHASE AND COACH",
      instruction: `${Math.round(s.late_rate * 100)}% of delivered orders arrived late (median ${s.late_median_slip.toFixed(0)} days late). Call the seller, agree a backlog plan, and re-check in two weeks.`,
    };
  }
  if (s.score_parts.trend >= 10) {
    return {
      action: "CHECK SEPTEMBER CAPACITY",
      instruction: `Late rate jumped in September (${Math.round(s.sep_late_rate * 100)}% vs ${Math.round(s.ja_late_rate * 100)}% in Jul-Aug). Something changed last month — capacity, staffing, or a new product line.`,
    };
  }
  if (s.score_parts.worst >= 10) {
    return {
      action: "REVIEW THE CATASTROPHIC SLIP",
      instruction: `One order arrived ${s.max_slip.toFixed(0)} days late (order ${s.worst_order_id}). The rate looks fine; the tail does not. Find out what happened before it repeats.`,
    };
  }
  if (route === "WATCH") {
    return {
      action: "MONITOR",
      instruction: "Below the action bar, but the slip pattern is visible. Re-score next month; no chase today.",
    };
  }
  return {
    action: "CHASE THE SELLER",
    instruction: `Late rate ${Math.round(s.late_rate * 100)}% with median late slip ${s.late_median_slip.toFixed(0)} days. Chase and set a check-in date.`,
  };
}

/** Mirror of Python scoring.chase_draft. */
export function chaseDraft(s: SellerRow): string {
  const { action, instruction } = recommendedAction(s);
  const lines = [
    `Subject: Delivery performance — ${s.seller_id.slice(0, 8)} (${s.seller_city}, ${s.seller_state})`,
    "",
    "Hi team,",
    "",
    `In Q3 2017 this seller delivered ${s.orders} orders. ${s.late_orders} arrived after the promised date (${(s.late_rate * 100).toFixed(1)}% late, median ${s.late_median_slip.toFixed(0)} days late, worst ${s.max_slip.toFixed(0)} days). ${(s.breach_rate * 100).toFixed(1)}% of items shipped after the shipping-limit date.`,
  ];
  if (s.overdue_open) {
    lines.push(
      `${s.overdue_open} order(s) are still past their promised date and undelivered as of ${SNAPSHOT_DATE}.`,
    );
  }
  if (s.reset_lead_time) {
    lines.push(
      `Recommended promise: ${s.recommended_promise_days} days (current median promise ${s.promised_median_days} days, p90 actual transit ${s.p90_transit_days} days).`,
    );
  }
  lines.push("", `Recommended action: ${action} — ${instruction}`, "", "This is a draft for a human to approve. Nothing has been sent.");
  return lines.join("\n");
}

export function statsFromRow(s: SellerRow): SellerStats {
  return {
    n: s.orders,
    late_orders: s.late_orders,
    late_rate: s.late_rate,
    late_median_slip: s.late_median_slip,
    max_slip: s.max_slip,
    breach_rate: s.breach_rate,
    sep_late_rate: s.sep_late_rate,
    sep_n: s.sep_n,
    ja_late_rate: s.ja_late_rate,
    ja_n: s.ja_n,
  };
}
